class Queue:
    def __init__(self):
        self.items = []

    def isEmpty(self):
        return self.items == []

    def enqueue(self, item):
        self.items.insert(0,item)

    def dequeue(self):
        return self.items.pop()

    def size(self):
        return len(self.items)

    def peek(self):
        if self.items:
	        return self.items[-1]
        else:
    	    return None

class Stack:

 def __init__(self):
 self.head = None

 def is_empty(self):
 return self.head is None

 def push(self, data):
 node = Node(data)
 node.next = self.head
 self.head = node

 def pop(self):
 if self.head is None:
 return None
 data = self.head.data
 self.head = self.head.next
 return data

