class Stack:

    def __init__(self):
        self.stack = []

    # Add to the top of stack
    def push(self, data):
        self.stack.append(data)

    # Remove from the top of stack
    def pop(self):
        if self.stack:
            return self.stack.pop()

    # Peek top element
    def peek(self):
        return self.stack[-1]

    # Check if stack is empty
    def is_empty(self):
        return not bool(self.stack)

class Stack:

    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.items:
            return self.items.pop()
        else:
            return None

    def peek(self):
        if self.items:
            return self.items[-1]
        else:
            return None

    def size(self):
        return len(self.items)

